\u0023\u004b\u0026\u0060\u0028\u0072\u0070\u002c\u0074\u0055\u0060\u006e\u005f\u0052\u0032\u0020\u0059\u0022\u005e\u004f\u0064\u006a\u0076\u004f\u0072\u0033\u004b\u0077\u0054\u0070\u007a\u0045\u006f\u005e\u0021\u0068\u004d\u0036\u003a\u0022\u0022\u005c\u0039\u003f\u002d\u0042\u0059\u0057\u0049\u0044\u004e\u006d\u0038\u007b\u0068\u0050\u0041\u0020\u0074\u0046\u0071\u0063\u0054\u0056\u0022\u003d\u0029\u0046\u0058\u007d\u005f\u0059\u0026\u007d\u0027\u0065\u004e\u0029\u0043\u002c\u002d\u0067\u0029\u0064\u0025\u007b\u003a\u0079\u003b\u0020\u0070\u0067\u003e\u0048\u0059\u003e\u0039\u004f\u0040\u0035\u0077\u002d\u0069\u0062\u0026\u0060\u004d\u0059\u0055\u0056\u003c\u002b\u0044\u004f\u0065\u0075\u0033\u0022\u0026\u0078\u0056\u006e\u0046\u0064\u0030\u006d\u007e\u002a\u0070\u0061\u003a\u006e\u0029\u002e\u0035\u0069\u004c\u0073\u006d\u002a\u0036\u0056\u0074\u0078\u005f\u0059\u0073\u005b\u0058\u003d\u0063\u003a\u0039\u0059\u0056\u003b\u007d\u005b\u0028\u005c\u0073\u0051\u0066\u004d\u006f\u0036\u0047\u0069\u0028\u0072\u004c\u005c\u0076\u0035\u003f\u0041\u006b\u0079\u0072\u002e\u007c\u007d\u003d\u0046\u007b\u003c\u0078\u005f\u003a\u0065\u005b\u0032\u0027\u0024\u002c\u004e\u002d\u0043\u003e\u0060\u0032\u002c\u005f\u0065\u007e\u0064\u007b\u0033\u0076\u0025\u002c\u005c\u0074\u007d\u0064\u0044\u003c\u007e\u0038\u0057\u0023\u007e\u0063\u0042\u0073\u006e\u003e\u0053\u0026\u0043\u005e\u003e\u002d\u007c\u0077\u0071\u0030\u007a\u0076\u007c\u0036\u0035\u0066\u0032\u0068\u005e\u0070\u0071\u007d\u0041\u0022\u0058\u0024\u0042\u0058\u007c\u007d\u0048\u0060\u002b\u0043\u0067\u0070\u0027\u0035\u005c\u007c\u002c\u0062\u0025\u0054\u007e\u0058\u0068\u0022\u0074\u0052\u003e\u0070\u0058\u003c\u0032\u002e\u004b\u0060\u003b\u007b\u0047\u0046\u0065\u0067\u006d\u006c\u007e\u007c\u007d\u007c\u0064\u0021\u0020\u007c\u0021\u0078\u0021\u0034\u004a\u004b\u0054\u0071\u0042\u0054\u002b\u003b\u007e\u0021\u004e\u0065\u0037\u005d\u007e\u0075\u002d\u003b\u006c\u0052\u003f\u0056\u0037\u004e\u0038\u006a\u0048\u0068\u0024\u0079\u007d\u006a\u0076\u0065\u0028\u0070\u0023\u0031\u0030\u0060\u0052\u0027\u003a\u0069\u006f\u004e\u0063\u0035\u005b\u0049\u0032\u0030\u0037\u0036\u005f\u0052\u0021\u007c\u006c\u003c\u0038\u0059\u0047\u0025\u0059\u0061\u0039\u0043\u0037\u0062\u0053\u007e\u0045\u0033\u0068\u0062\u0045\u006f\u0044\u003f\u0069\u0068\u0063\u002a\u002d\u004b\u0032\u0042\u0077\u0071\u003c\u0021\u003a\u002d\u0056\u002b\u005a\u006d\u0032\u004e\u002f\u0050\u0071\u0051\u005d\u004d\u003e\u0049\u0045\u0040\u003b\u007c\u0048\u004a\u0034\u0053\u0028\u002c\u004c\u0060\u003c\u0074\u0038\u0042\u0076\u0051\u0037\u004c\u005d\u0051\u004b\u0058\u0032\u0061\u0057\u007c\u0024\u0038\u0024\u0024\u0079\u005e\u0047\u0051\u0034\u0056\u0036\u0056\u002f\u0061\u004b\u0030\u0045\u007b\u0052\u0041\u002c\u0065\u003c\u007e\u0033\u0062\u003b\u0042\u0074\u0039\u005b\u0023\u0022\u0073\u0077\u0072\u0071\u0075\u007a\u0058\u0047\u0020\u005e\u006b\u0026\u0026\u0074\u0068\u007a\u0064\u007b\u0031\u0037\u002f\u003e\u005e\u0028\u0023\u0045\u0079\u0074\u0034\u002e\u0027\u003e\u006b\u0047\u0066\u0029\u0023\u0053\u0051\u0053\u0061\u006c\u0050\u002f\u007c\u0022\u006b\u004d\u002e\u002b\u002b\u0037\u0044\u003e\u005a\u006a\u006a\u0039\u0066\u002b\u002c\u0024\u006c\u002e\u002b\u006a\u0058\u0041\u004c\u0060\u0068\u0040\u0039\u0045\u0068\u005b\u0052\u0038\u0049\u006e\u0036\u002b\u0036\u0038\u0036\u002b\u004c\u002f\u003a\u005b\u006c\u005e\u006a\u0061\u0022\u0053\u006d\u004c\u0029\u0043\u005e\u004f\u0028\u0021\u0068\u006f\u0066\u0054\u006f\u002e\u0074\u005b\u0030\u0024\u0038\u005d\u0055\u006c\u0030\u006d\u0070\u0039\u004f\u005c\u0039\u0067\u0032\u0041\u0060\u0020\u0063\u007b\u0049\u0067\u007e\u003d\u0028\u0037\u006e\u0042\u0061\u0028\u007e\u0043\u0021\u0037\u0057\u0052\u0024\u0076\u0066\u0036\u0044\u0070\u004c\u0075\u0061\u0043\u0031\u006a\u0058\u0064\u0020\u0061\u0078\u0075\u004c\u0079\u0021\u0058\u002d\u0026\u0055\u002f\u0036\u003a\u004e\u0056\u0059\u003c\u0050\u003b\u003a\u007d\u002e\u004e\u0030\u0046\u0043\u0024\u007e\u006f\u005d\u003f\u0030\u0030\u0029\u0042\u002c\u0020\u0059\u003a\u004c\u0074\u0060\u002e\u0034\u003d\u002d\u0061\u0023\u0049\u0071\u0031\u004c\u007b\u0047\u005f\u0063\u007e\u005f\u0048\u0035\u006c\u007b\u0050\u0071\u0070\u002b\u0038\u006b\u005d\u0077\u0040\u005b\u003c\u0064\u0069\u0069\u0068\u002e\u004c\u0028\u007a\u0078\u007a\u007e\u0034\u0062\u0048\u0051\u0025\u0048\u007e\u003e\u006d\u007b\u0064\u0038\u005d\u0054\u0079\u0053\u0040\u0030\u004e\u0027\u0058\u004e\u003c\u0063\u0036\u0065\u002d\u002f\u0048\u0030\u0071\u0032\u0041\u0063\u0030\u0069\u007b\u0052\u0047\u005a\u0052\u0032\u005b\u003a\u0027\u0073\u0069\u0051\u007c\u006b\u003e\u003a\u004c\u003a\u0038\u0069\u0032\u0040\u006a\u006b\u0049\u0070\u0075\u0053\u0064\u004b\u0021\u0077\u0020\u0025\u002a\u0044\u0040\u002b\u002a\u0028\u0026\u0035\u0055\u003d\u0022\u005e\u0063\u0024\u004a\u0026\u006d\u0045\u004f\u0038\u007e\u005a\u0020\u0076\u0032\u0069\u007e\u0068\u006b\u006f\u0063\u0068\u0037\u0059\u0021\u007b\u0034\u0065\u007b\u0030\u006e\u004f\u006d\u0066\u003b\u0070\u006e\u007b\u0079\u0034\u0040\u007b\u007e\u005f\u0034\u002b\u0061\u0057\u005a\u002c\u0036\u0055\u006f\u005a\u0031\u004f\u006b\u0021\u0034\u0045\u002b\u003c\u0051\u0021\u0070\u0070\u002c\u0040\u0076\u0052\u003d\u0026\u0077\u0029\u0037\u0035\u005a\u0045\u0028\u0046\u0030\u005f\u0057\u0045\u0036\u006f\u004a\u0079\u005c\u004f\u0023\u0044\u0075\u0035\u0022\u0069\u003d\u002d\u005c\u0036\u003b\u0078\u0068\u0071\u004c\u007c\u0044\u003b\u005d\u004d\u003e\u006c\u0070\u0048\u0036\u0044\u005a\u0045\u0057\u0060\u0039\u006e\u004f\u0021\u0049\u0036\u0039\u0056\u0030\u0067\u0077\u0033\u0059\u0078\u0044\u0076\u0035\u006b\u0031\u0025\u0024\u0045\u003a\u002b\u0074\u004d\u0039\u0049\u004f\u0056\u0050\u0031\u002c\u0045\u004b\u0029\u0069\u0052\u003d\u006d\u0037\u004c\u0021\u006d\u004d\u0046\u0058\u0034\u0039\u006f\u0052\u0040\u004b\u007d\u0070\u0032\u0065\u0056\u0049\u006f\u0059\u004b\u006f\u0034\u0077\u0052\u0023\u0047\u003a\u0077\u005b\u004c\u0056\u0050\u0034\u0066\u007e\u003a\u0045\u0075\u0034\u0028\u0022\u0036\u003c\u0059\u0069\u006b\u0026\u007c\u0073\u004a\u0042\u004a\u002a\u0066\u005d\u0049\u0035\u0059\u003c\u0067\u0023\u0020\u0033\u0057\u0060\u007d\u0047\u0042\u0035\u007d\u0027\u005f\u0071\u0055\u007c\u0053\u0064\u004b\u0064\u0055\u002a\u0039\u0044\u0072\u0037\u0053\u0056\u0044\u0066\u0047\u0037\u0043\u0054\u0028\u0063\u0058\u0022\u004b\u0036\u003b\u0025\u0045\u0037\u005a\u0060\u002f\u007a\u0033\u0035\u0041\u0077\u0068\u0062\u0068\u007c\u002d\u007b\u0051\u0055\u004f\u0049\u003a\u0028\u0075\u0067\u0066\u0040\u007d\u0046\u0063\u004e\u0064\u004c\u0050\u0027\u0072\u007c\u0064\u0038\u0039\u0039\u0067\u007e\u006c\u007b\u0034\u006a\u003d\u0055\u0022\u004c\u0040\u0052\u0038\u0062\u006b\u0047\u003f\u004a\u0076\u005d\u0073\u0022\u0040\u0071\u007d\u0021\u002b\u0056\u002a\u0036\u0054\u002c\u0069\u0021\u0045\u003c\u0059\u006b\u0063\u0023\u0031\u007a\u003a\u0079\u007d\u0034\u0025\u0034\u004d\u0077\u0044\u006a\u0068\u0060\u0030\u0069\u005f\u004b\u005a\u0079\u0046\u007c\u0048\u0078\u0073\u0058\u0071\u004e\u0058\u0046\u0027\u0023\u007a\u0035\u0060\u0059\u0059\u005a\u005b\u0061\u0064\u0064\u006a\u0063\u0066\u005d\u006c\u0053\u0035\u007d\u0033\u0045\u007e\u0065\u0067\u0048\u0056\u0065\u0056\u007e\u0065\u004c\u0033\u0042\u007a\u0029\u0022\u002a\u005f\u0058\u0043\u002e\u004a\u0041\u0050\u0071\u0050\u0058\u0063\u0063\u0041\u0067\u0071\u0077\u0035\u004d\u0068\u007a\u005b\u0061\u0062\u0079\u003e\u0062\u0029\u003f\u0077\u0020\u0053\u0062\u0039\u006e\u0060\u0042\u0035\u0065\u005b\u0070\u002c\u0079\u0031\u0046\u0062\u007c\u0042\u0066\u0064\u0061\u0055\u0078\u006a\u005a\u0053\u0046\u004d\u0036\u0024\u0079\u0032\u0071\u0047\u0023\u007a\u0030\u0052\u0026\u0064\u0070\u0030\u0041\u0070\u0059\u0076\u0072\u0061\u0056\u0071\u0069\u006c\u0066\u0035\u0033\u0035\u0031\u004d\u004d\u003d\u0032\u006d\u003e\u0059\u0070\u0062\u007e\u0023\u0053\u0040\u006a\u0049\u0057\u0060\u007d\u006c\u0041\u0079\u007e\u007c\u0069\u005e\u0036\u006f\u004f\u004c\u0033\u0033\u003a\u007b\u005f\u0065\u004a\u0050\u0068\u0040\u002d\u0078\u0051\u003d\u0027\u0050\u007d\u0035\u0074\u002b\u0057\u0044\u006f\u004f\u0036\u006d\u0077\u0079\u0063\u007d\u004d\u002d\u002c\u002e\u0034\u0073\u0021\u002a\u004c\u0044\u003a\u0060\u0072\u0066\u0063\u0030\u0069\u0075\u0045\u0031\u003d\u003d\u0020\u007d\u0042\u0066\u0036\u0021\u0055\u0072\u0063\u0066\u0030\u0041\u002c\u0046\u0046\u0055\u0069\u004f\u0033\u0033\u003b\u007b\u002c\u0030\u0034\u004f\u002a\u0071\u007c\u0077\u0046\u0021\u0047\u004f\u006f\u0025\u0024\u002c\u0022\u0059\u003d\u002f\u0049\u0037\u0049\u006c\u003e\u007e\u0042\u0032\u006e\u003b\u005d\u0045\u0031\u007b\u0065\u0030\u0068\u002a\u007d\u0063\u0071\u003a\u006e\u0059\u0041\u0037\u0053\u004b\u0068\u0023\u0051\u003d\u0046\u002f\u002f\u0063\u0064\u0054\u005b\u005b\u0052\u0049\u0069\u004c\u002b\u0029\u0032\u007d\u007c\u0057\u004c\u0041\u0033\u007a\u0031\u0039\u0067\u004e\u0028\u0030\u0067\u0044\u0020\u006c\u0050\u0026\u003a\u004e\u004a\u0030\u0026\u0059\u0033\u005b\u0033\u0030\u003f\u0054\u004c\u005c\u0061\u0057\u003f\u006b\u004e\u003d\u0031\u0068\u005c\u005a\u0055\u0045\u0051\u0069\u002d\u002a\u0044\u003a\u005e\u0030\u0044\u004f\u0022\u0058\u003f\u0078\u0078\u0058\u0063\u0073\u007e\u0050\u0060\u006a\u006b\u003c\u0067\u0045\u0027\u004f\u0066\u002e\u004a\u003f\u0076\u006f\u0055\u005f\u0068\u0072\u0024\u0028\u004a\u0070\u0064\u007d\u005e\u003f\u003d\u0036\u0026\u007c\u004b\u0068\u0077\u0051\u0049\u002a\u0027\u002b\u006b\u0067\u0051\u002f\u004e\u006a\u0051\u006c\u007b\u0035\u0036\u0054\u003b\u0059\u0040\u0070\u0051\u002b\u0075\u0059\u0076\u0061\u005c\u0036\u0072\u0056\u0022\u0037\u0038\u007b\u007c\u0054\u0027\u0061\u0024\u006d\u0073\u0036\u006a\u0034\u0051\u006d\u005b\u003f\u005c\u0037\u0070\u004e\u0068\u0045\u0043\u0022\u004d\u006e\u0067\u0049\u0033\u003f\u006e\u0021\u0046\u0036\u0073\u0063\u0048\u002e\u0037\u003d\u0034\u004c\u0070\u007d\u002f\u004d\u006a\u0046\u004b\u0055\u0077\u005d\u0045\u007a\u0022\u002d\u0075\u0054\u0074\u005f\u003c\u0031\u0049\u003d\u0076\u0045\u0068\u004c\u007a\u0069\u0063\u0035\u006d\u0073\u0059\u0052\u0052\u0049\u0041\u002d\u0033\u0065\u0034\u0036\u004d\u0073\u0061\u0072\u0032\u0021\u0066\u0031\u004a\u006e\u005e\u006e\u0065\u0048\u0041\u0079\u0041\u0069\u0043\u0065\u003a\u0029\u002c\u0040\u002e\u0054\u0069\u0043\u0039\u0053\u0070\u0033\u0050\u004c\u0068\u0046\u005f\u0043\u0041\u0049\u005f\u0042\u0047\u0032\u005d\u0063\u0066\u0032\u0071\u0036\u005d\u004c\u005d\u0076\u007a\u004f\u0077\u004f\u003e\u0034\u004a\u0071\u0078\u0073\u0036\u0075\u0035\u0025\u002e\u007d\u0064\u0066\u0041\u0031\u0059\u007c\u003d\u0051\u0027\u0031\u0077\u0021\u0067\u0051\u005a\u0032\u0048\u0022\u002f\u0028\u0041\u005b\u0065\u0074\u0025\u003e\u0066\u002f\u0021\u002b\u0077\u005b\u0031\u0024\u0027\u0075\u005f\u007e\u004c\u0054\u0074\u0048\u004a\u0025\u0036\u0076\u0028\u0077\u006e\u0022\u0079\u0053\u007d\u0054\u0066\u0058\u0076\u0057\u003b\u0070\u0066\u0072\u0068\u0049\u0075\u0021\u0031\u0068\u0039\u003f\u0040\u0077\u0072\u0076\u0050\u004c\u0040\u005d\u002b\u0041\u0028\u0056\u006b\u003a\u0046\u0046\u0027\u0043\u0060\u0070\u0055\u0063\u0031\u004f\u0056\u006d\u0034\u0072\u005d\u0043\u0023\u0067\u003f\u003f\u0049\u0044\u0056\u0027\u0032\u0048\u0045\u007b\u007a\u0078\u0077\u0035\u005c\u006e\u0036\u004f\u0066\u007c\u0048\u006c\u0029\u0034\u003c\u0029\u0056\u0073\u007a\u002c\u0046\u004d\u0037\u003b\u0070\u003d\u002f\u004f\u0026\u0065\u0063\u0032\u005c\u0079\u005d\u0030\u0069\u007c\u0025\u0052\u0041\u003e\u0062\u0036\u007c\u0069\u0075\u0061\u0048\u007c\u0034\u0031\u002e\u0044\u0035\u0048\u002f\u005d\u0024\u0066\u0028\u0059\u0055\u0059\u0036\u005b\u0059\u0025\u0059\u005d\u0049\u007a\u006b\u0025\u0027\u005b\u0046\u0026\u0020\u0064\u004b\u003f\u0077\u0060\u0022\u003b\u003a\u0062\u0070\u005a\u0020\u0050\u0033\u0026\u0049\u002b\u005d\u002d\u0068\u007b\u002d\u0050\u005f\u002e\u0027\u0074\u002b\u0053\u0030\u0040\u0058\u003b\u004e\u0046\u007c\u006b\u006e\u0027\u004d\u0029\u0066\u0078\u003a\u002c\u0045\u004c\u0031\u0064\u0037\u0040\u002d\u0047\u0057\u002a\u0037\u0034\u0058\u0062\u003e\u0073\u0050\u0061\u0070\u002f\u0020\u0029\u0025\u0036\u0056\u006d\u0041\u007e\u0039\u0035\u0073\u0040\u0061\u0059\u0053\u0051\u003d\u007e\u0041\u0070\u0056\u0063\u0070\u006b\u004f\u0039\u005c\u007c\u0023\u006d\u003e\u0060\u006b\u006f\u0059\u007c\u004d\u0053\u005b\u006b\u0053\u0057\u0059\u002e\u007d\u0071\u0057\u0042\u0076\u0027\u0039\u004d\u003a\u0033\u0036\u0036\u002e\u007c\u002e\u005f\u004f\u0075\u0025\u0042\u005d\u0068\u0043\u0050\u0071\u0076\u005f\u007e\u0027\u0021\u0061\u0033\u0050\u0032\u0077\u0065\u0041\u0050\u0042\u005d\u0034\u003c\u0035\u006b\u004d\u0050\u0044\u003a\u0036\u0060\u007b\u0022\u0023\u0034\u0037\u005e\u0041\u0071\u004f\u003a\u007b\u0068\u0078\u0035\u0061\u0039\u0045\u005b\u0076\u0025\u0042\u0037\u0049\u0021\u0025\u0055\u0068\u0039\u006a\u002c\u0066\u003a\u0035\u003f\u004a\u0029\u004b\u0057\u005d\u004b\u0034\u0044\u0030\u0072\u007b\u0040\u0054\u007e\u007b\u005c\u0048\u0027\u006b\u003c\u002a\u002c\u0061\u0064\u005f\u0074\u003c\u0047\u002a\u0052\u0057\u0028\u0062\u006d\u0031\u007c\u002b\u0060\u006f\u0028\u0047\u0067\u0040\u0073\u0062\u0041\u003d\u0047\u0078\u0057\u0050\u002c\u0051\u0048\u0058\u002f\u0034\u003f\u0022\u0055\u003f\u005f\u0032\u0061\u003b\u0066\u0027\u006b\u0057\u0031\u0049\u002c\u0057\u0046\u0075\u004a\u0055\u0078\u0047\u002a\u002d\u0026\u0053\u004b\u0029\u0023\u0050\u007b\u0053\u004d\u0045\u004f\u0046\u007e\u0071\u005c\u0033\u0030\u0064\u002d\u005f\u0041\u0077\u004d\u0073\u0022\u0062\u004c\u006f\u0078\u0049\u002d\u0069\u003a\u0021\u002b\u0041\u0064\u002f\u0046\u0050\u004d\u004a\u005f\u002f\u004b\u0077\u004e\u002b\u0039\u0067\u005d\u0030\u006d\u004b\u0066\u0026\u0068\u004a\u005e\u0030\u006a\u0069\u004e\u003a\u007a\u0068\u004f\u0041\u0047\u0031\u0072\u0022\u0054\u0032\u007d\u0038\u0070\u003a\u0035\u006a\u0061\u0026\u002e\u0036\u0073\u004b\u0020\u0051\u0041\u0039\u007d\u0054\u0060\u006a\u0036\u005a\u0045\u0063\u0059\u003a\u0049\u0026\u0034\u0065\u0028\u0028\u0045\u005f\u0065\u0048\u005b\u0068\u0074\u0029\u0022\u006f\u0065\u0035\u0030\u006b\u0032\u0069\u0036\u003c\u006e\u0033\u007e\u006e\u004a\u0046\u0031\u0050\u004d\u0063\u0072\u003c\u0029\u004c\u005f\u0049\u0050\u0042\u0034\u0042\u0067\u0035\u0051\u0043\u006b\u007e\u007e\u003e\u0032\u007a\u002e\u004a\u0061\u0020\u005e\u0045\u0062\u006b\u007c\u002b\u0036\u0062\u0042\u0044\u0061\u007a\u0070\u0037\u0070\u003e\u0064\u0079\u0056\u0047\u0037\u0061\u003f\u0051\u0042\u0022\u005e\u0052\u0034\u006b\u0030\u002e\u002a\u0026\u005f\u004b\u0067\u0029\u005f\u0047\u0041\u0059\u006c\u002f\u006a\u007a\u0043\u0025\u0064\u0047\u0040\u002f\u0040\u002b\u006b\u004b\u005b\u0056\u0058\u002f\u0048\u002c\u002e\u0079\u0023\u006e\u007a\u003e\u0026\u0065\u0029\u002c\u0063\u005f\u0053\u0070\u0067\u004f\u0066\u005f\u006c\u0074\u0060\u004c\u0035\u0061\u0042\u007b\u005f\u0046\u0041\u0036\u0069\u0068\u004d\u0050\u005e\u007a\u003e\u002d\u006b\u005e\u0036\u005b\u006d\u005c\u0028\u0065\u002a\u0032\u0030\u007d\u004b\u0049\u005a\u006a\u0024\u002b\u0071\u0055\u0029\u0049\u0035\u005e\u0023\u0049\u002e\u0054\u003b\u004c\u0073\u005f\u003a\u003d\u0031\u003f\u006c\u0076\u003c\u005a\u0075\u004a\u0042\u0078\u007b\u0072\u006a\u0077\u0036\u005a\u0074\u0046\u0043\u004a\u0028\u002c\u0038\u007b\u0033\u0039\u0052\u003f\u006b\u003a\u004f\u0058\u0079\u0051\u0068\u002f\u004c\u0057\u0055\u0049\u0031\u006e\u0020\u0046\u003c\u005a\u0078\u0067\u0038\u0060\u0034\u0071\u0065\u0046\u0042\u0032\u0059\u006f\u0070\u002e\u0038\u004b\u003c\u0023\u0056\u0078\u007c\u003a\u002b\u0077\u004b\u007a\u0047\u0034\u0038\u0025\u0048\u0068\u0070\u002f\u0036\u0079\u0031\u0027\u0027\u0079\u006d\u0060\u0033\u0053\u0028\u0041\u0044\u002c\u0054\u003b\u003e\u0053\u0042\u0044\u0055\u0055\u0045\u0032\u0069\u0060\u002c\u0065\u0069\u002b\u0076\u006d\u0037\u006f\u0079\u004c\u0027\u005e\u0022\u0029\u004d\u0058\u0035\u0045\u003e\u0068\u0034\u003d\u0033\u0028\u0060\u004a\u006e\u0048\u006b\u0056\u0058\u006f\u0070\u003f\u0026\u002c\u0050\u0032\u0075\u0033\u0056\u007b\u0037\u0059\u005a\u004d\u002c\u005a\u0045\u0055\u0020\u0030\u002c\u0049\u0050\u0065\u0046\u007b\u0048\u0027\u003c\u004d\u004f\u007a\u007c\u0032\u004d\u0059\u0049\u0027\u0059\u0036\u0062\u006d\u0056\u007b\u0069\u0043\u0064\u0045\u002c\u0065\u003d\u004d\u005d\u0043\u0061\u0073\u007e\u0079\u007c\u0030\u003b\u0065\u005f\u004e\u0057\u0038\u005a\u0052\u005a\u002d\u0033\u0052\u002b\u0071\u0049\u004d\u004b\u0057\u0024\u005f\u0027\u002d\u003f\u0041\u007e\u002c\u006c\u0060\u003c\u0055\u002b\u003d\u003c\u003b\u005e\u0057\u0059\u006f\u0021\u0039\u0074\u002a\u004f\u0046\u0048\u005d\u002a\u004c\u0028\u0037\u0056\u005b\u005d\u0067\u007a\u0060\u003b\u0046\u0065\u005c\u002d\u0062\u005e\u0061\u0035\u0055\u0050\u0078\u0026\u005c\u003d\u0063\u005c\u005d\u006d\u006a\u002e\u002d\u0079\u0068\u004c\u0028\u0036\u0025\u0060\u0050\u0037\u002a\u006f\u0044\u006f\u0029\u0034\u0073\u0054\u0035\u0077\u003b\u0065\u0071\u005d\u0024\u0037\u0039\u002b\u0064\u0044\u0055\u0027\u0079\u002f\u005f\u004e\u0031\u005c\u0030\u002b\u003a\u003f\u0044\u003f\u002d\u004a\u0022\u003d\u0069\u004e\u0048\u0037\u004c\u0039\u005b\u0046\u007a\u0028\u0032\u004b\u0027\u007d\u0038\u007b\u0054\u002d\u003b\u0047\u004d\u0066\u005e\u0078\u006b\u0042\u005f\u0040\u0063\u0079\u0077\u0068\u006f\u005b\u002b\u0060\u0074\u0029\u0047\u0039\u0075\u003e\u0064\u007c\u003e\u003c\u003a\u005d\u004d\u004e\u0021\u006e\u0047\u0020\u0041\u0028\u004a\u0076\u004d\u0052\u006b\u007a\u0028\u0055\u0045\u007c\u0021\u0074\u0033\u0078\u0041\u0039\u0065\u006b\u0073\u0029\u0051\u006b\u0056\u0025\u006b\u007d\u006c\u004b\u0076\u0063\u0052\u0064\u0026\u0039\u004d\u0069\u006a\u004a\u0034\u0039\u0053\u0067\u0032\u002c\u0067\u0052\u0064\u0063\u007c\u0072\u0020\u006c\u0068\u0042\u0046\u007d\u003f\u0050\u0045\u006e\u0055\u0020\u006e\u006f\u002f\u002e\u007d\u0031\u004d\u005d\u0073\u006a\u005c\u0024\u0032\u007b\u0025\u004c\u0044\u0040\u0037\u0053\u0020\u0039\u007c\u0044\u0055\u0024\u004f\u0050\u0051\u007b\u0047\u006f\u005c\u0035\u0058\u002e\u0049\u0045\u0057\u003e\u002b\u0056\u006e\u005c\u006a\u003d\u0038\u0035\u005d\u0040\u002c\u0046\u0021\u005d\u006b\u0024\u004b\u0054\u0058\u0046\u0053\u005b\u0073\u002a\u0034\u007b\u0053\u0033\u006b\u0079\u0040\u0031\u003c\u007e\u005a\u0059\u0033\u003e\u0041\u0065\u003b\u0079\u0056\u007a\u006a\u005d\u0040\u0043\u0065\u0058\u007a\u0067\u0079\u0044\u003d\u0042\u0044\u0036\u007e\u0037\u0058\u0025\u0041\u0054\u0054\u0059\u0030\u0078\u004b\u0025\u0046\u0026\u007c\u005b\u002c\u0063\u0050\u0066\u0045\u002b\u0079\u0057\u007c\u0055\u007c\u0033\u0050\u005b\u0022\u0026\u002d\u006b\u0067\u0059\u0043\u003b\u0054\u0048\u005a\u0057\u0022\u0028\u005a\u002f\u002b\u0042\u0064\u0033\u0036\u0052\u0044\u0038\u006f\u003e\u0060\u003e\u0057\u0060\u004b\u003e\u0079\u0055\u005b\u004d\u002f\u006e\u0030\u0054\u002a\u005b\u0050\u0079\u006f\u002d\u0060\u006f\u0037\u0056\u0028\u0050\u002f\u004c\u002b\u005b\u0026\u003e\u003f\u0032\u0043\u0028\u007e\u0041\u003c\u0049\u007d\u005b\u002d\u007c\u0063\u0042\u0048\u0034\u004a\u0076\u0039\u0051\u0036\u0056\u004a\u007b\u0032\u0050\u0077\u004c\u0042\u0047\u0025\u0063\u005c\u0068\u0021\u005d\u0070\u0058\u0062\u0034\u002d\u0035\u0028\u005a\u003e\u005e\u004c\u0024\u002d\u002c\u004b\u0037\u0052\u0031\u003f\u0060\u0078\u003c\u0038\u0041\u0048\u0041\u006a\u0039\u002a\u0075\u006a\u004d\u0036\u0054\u002d\u0032\u0025\u0071\u005b\u005c\u005d\u0054\u0033\u0063\u0045\u004d\u0078\u0053\u0073\u007a\u0046\u0058\u0053\u0036\u0047\u005f\u007b\u0029\u0023\u006e\u0078\u0056\u0058\u006f\u007e\u006b\u0072\u006e\u002a\u0055\u007e\u005d\u005b\u003c\u0022\u0070\u0069\u0054\u006b\u002e\u007a\u0047\u0021\u0047\u0058\u0070\u003c\u0055\u0036\u0055\u0058\u0040\u0045\u0072\u0059\u0034\u006c\u0069\u0048\u0041\u0053\u0029\u0063\u004e\u0021\u006c\u006c\u0036\u004f\u0071\u0035\u0025\u0036\u0044\u0024\u005e\u0053\u0029\u002a\u0065\u0037\u0068\u0063\u003c\u0053\u0022\u007b\u005b\u005e\u0057\u0054\u003d\u004b\u0060\u0045\u0070\u007e\u0053\u0035\u0033\u006c\u0030\u0062\u006c\u003a\u007e\u0069\u0036\u0036\u0044\u0055\u0030\u004e\u0038\u004d\u0028\u004b\u0055\u0024\u0043\u0024\u0034\u0032\u0030\u007b\u0025\u006f\u006d\u0062\u006c\u0038\u0044\u002a\u0061\u0071\u0022\u0072\u0040\u0064\u0039\u0044\u006f\u0020\u0020\u0054\u0063\u0034\u0066\u0034\u006a\u0029\u0021\u003c\u0026\u006c\u0074\u002a\u0062\u0047\u0035\u0029\u0051\u0046\u003f\u0047\u005e\u0039\u0044\u0061\u003a\u0078\u003e\u006c\u0054\u0029\u0079\u0035\u0043\u0055\u0052\u0033\u002a\u0039\u002e\u0037\u0022\u004e\u0049\u0027\u003d\u004c\u0026\u0057\u0027\u0050\u003d\u0074\u0079\u005e\u002b\u0044\u002a\u0030\u005c\u0043\u0065\u0038\u0062\u0061\u004a\u0074\u0073\u005d\u0037\u004a\u0062\u006c\u007b\u0058\u0040\u0048\u007d\u0037\u0028\u007b\u002f\u0058\u0037\u0057\u004e\u0043\u0026\u0028\u0025\u005f\u0049\u0060\u003a\u002f\u0079\u0049\u0020\u0076\u0044\u005b\u0021\u0030\u0042\u0044\u0031\u0078\u0054\u007c\u005c\u0037\u003b\u004b\u0052\u004e\u005c\u0072\u002f\u002c\u0032\u0042\u0074\u004a\u003b\u0020\u006d\u0026\u0076\u004b\u002d\u006d\u004b\u0020\u0024\u005c\u003f\u0046\u003b\u002e\u0044\u0023\u004a\u0067\u002d\u0025\u0078\u0074\u0054\u0053\u005d\u0031\u0037\u002d\u002d\u007c\u0020\u0069\u004e\u0033\u0039\u0068\u0044\u0074\u005c\u002b\u0063\u0051\u004f\u0027\u0037\u0049\u0054\u004b\u0022\u007c\u003f\u0037\u0066\u0026\u003d\u007a\u0028\u0027\u0026\u004f\u004c\u003b\u002c\u0047\u0048\u0040\u0037\u007e\u002f\u0067\u0078\u0034\u0033\u004f\u0061\u0076\u0062\u0028\u002c\u0046\u0040\u0039\u0074\u002f\u0029\u002e\u006f\u0067\u002d\u002a\u0049\u0023\u0051\u0066\u003f\u0076\u0033\u0048\u0059\u0047\u0057\u006b\u0037\u0051\u0029\u0074\u003a\u002d\u0026\u0043\u0064\u0047\u0060\u0059\u0048\u005f\u004c\u006d\u002b\u005f\u007d\u002b\u0020\u0054\u0029\u003e\u0032\u0064\u006c\u0029\u004d\u0041\u0065\u0055\u0023\u0029\u002b\u005b\u0025\u0027\u0048\u007a\u003f\u0032\u003f\u0076\u006c\u004f\u005a\u003a\u0061\u0055\u003e\u0071\u0021\u0052\u006b\u0073\u0041\u0053\u0041\u0045\u007a\u0070\u0067\u0030\u0031\u0037\u0052\u003e\u006f\u0053\u007e\u007d\u0048\u0041\u0041\u0024\u003f\u0077\u0025\u0022\u0072\u0040\u003a\u0043\u0059\u0023\u002e\u0052\u0048\u0046\u0049\u0065\u002d\u0071\u0060\u0032\u0069\u007d\u005a\u0023\u0054\u0075\u0064\u0069\u0070\u0020\u0032\u007d\u0071\u0063\u0076\u0045\u0046\u0056\u0039\u0025\u0038\u0048\u004d\u0068\u0055\u002d\u0049\u002a\u006c\u006f\u007e\u0039\u005b\u0035\u0049\u002f\u0025\u003d\u0046\u004e\u0055\u0040\u0021\u0037\u003c\u0060\u002b\u0068\u002c\u0028\u004c\u0023\u006b\u0042\u0074\u007b\u0054\u006d\u0068\u0042\u0061\u0022\u0054\u0048\u0025\u002e\u0069\u004c\u0045\u0060\u0075\u005f\u0071\u0021\u007e\u0041\u0070\u0060\u0073\u007d\u0042\u003b\u0070\u0066\u0074\u005d\u005d\u0040\u0064\u0066\u0036\u004d\u002e\u006c\u004d\u004f\u0039\u006f\u0020\u002f\u005c\u0037\u0034\u007a\u0044\u0058\u0067\u006a\u005f\u0034\u0024\u006e\u0074\u005c\u0020\u0054\u006a\u0033\u0050\u006d\u0044\u0050\u0027\u0055\u0061\u005c\u0036\u006f\u0069\u003d\u0026\u0067\u0051\u003b\u0068\u0054\u003b\u006f\u0058\u004c\u0065\u007e\u0077\u0077\u003d\u0075\u003b\u0075\u0021\u007a\u0065\u006b\u0058\u0051\u004f\u0061\u007d\u0074\u0023\u002a\u004e\u0037\u004a\u0049\u0030\u005b\u0035\u003c\u0071\u0024\u0053\u0074\u002e\u0034\u0023\u0070\u007d\u0065\u003a\u0055\u004d\u0058\u0074\u0044\u005c\u006f\u0058\u0027\u007a\u0038\u003d\u004c\u0040\u0037\u0078\u005c\u007d\u002a\u0030\u0074\u0050\u0058\u0057\u0066\u0078\u0074\u003d\u005e\u0063\u0044\u0055\u0026\u005a\u0071\u006f\u0032\u0038\u0074\u005b\u002e\u0021\u007d\u006f\u002e\u006d\u0023\u0036\u003c\u0031\u0030\u0020\u0050\u007d\u0051\u0028\u005b\u0037\u0023\u007a\u005d\u0036\u0060\u0065\u0025\u0061\u0038\u0041\u007e\u0058\u0046\u002f\u003f\u0077\u0038\u005c\u0025\u0035\u0063\u003f\u002f\u0047\u005c\u0028\u0061\u0021\u006b\u006a\u007d\u0062\u007e\u0040\u0079\u0030\u005f\u006d\u0040\u0021\u004a\u0046\u0034\u003d\u005d\u0046\u0069\u006f\u004f\u0021\u006e\u0059\u002b\u004f\u002f\u003a\u0025\u0077\u003d\u0059\u0078\u0061\u0071\u006e\u0071\u0039\u0058\u0072\u005f\u0042\u0068\u0064\u0032\u006a\u007e\u0058\u002f\u0022\u0077\u004c\u0077\u005f\u002c\u0027\u0065\u002b\u006b\u0056\u0066\u0062\u003d\u002a\u005c\u0065\u003d\u0061\u0040\u002c\u002f\u0050\u0044\u003f\u007a\u0025\u0025\u0063\u002d\u004a\u003e\u004d\u005b\u003f\u0058\u0027\u0037\u006b\u002c\u0031\u0042\u0043\u003b\u0043\u0031\u005f\u003d\u0074\u007a\u004b\u0033\u0039\u0069\u0056\u0063\u004f\u0052\u0028\u003d\u0040\u0069\u0044\u0035\u0025\u0078\u002d\u006f\u0041\u0031\u0041\u0029\u002f\u0067\u005c\u0031\u005a\u002e\u004e\u0025\u006b\u0034\u0038\u0050\u0025\u004c\u003f\u0033\u004e\u0071\u007d\u0026\u0079\u002c\u0064\u0046\u0039\u0050\u003d\u004f\u0020\u0075\u006f\u005e\u006e\u0078\u0060\u004b\u0047\u0048\u004f\u0027\u0063\u0055\u004c\u0068\u0028\u0049\u004b\u0043\u0047\u0067\u0039\u0027\u007b\u0071\u0036\u003a\u005a\u005f\u0052\u0065\u0067\u0066\u0032\u0043\u007e\u005f\u004a\u0076\u0050\u007e\u0058\u003f\u0026\u006a\u0024\u006f\u0042\u0032\u0026\u0040\u0021\u003a\u003c\u0076\u0058\u0068\u007b\u0076\u0043\u0042\u0031\u0022\u0073\u0031\u0049\u0037\u006b\u0050\u0040\u0037\u0067\u007e\u0032\u003f\u0021\u003d\u003b\u0021\u004b\u005d\u0050\u0030\u0036\u005e\u0049\u0033\u004a\u0041\u0038\u0055\u0072\u0065\u0051\u005e\u0062\u0071\u007d\u0038\u002a\u0051\u007d\u006e\u004f\u003f\u0075\u0054\u005a\u0028\u0078\u004a\u0035\u007d\u005c\u007a\u004d\u0079\u0071\u0037\u0057\u002c\u0061\u0046\u003b\u0075\u004b\u0032\u003b\u0060\u005a\u004f\u004f\u002e\u0043\u0038\u0063\u0069\u007a\u0073\u0040\u0035\u0035\u0077\u0061\u0056\u0025\u0023\u0044\u0026\u0037\u007b\u0072\u005d\u0067\u0025\u007d\u0071\u0030\u0041\u005d\u0065\u0033\u0056\u0020\u0028\u0075\u0061\u004c\u003c\u0026\u0048\u0076\u002c\u003f\u0031\u003b\u002f\u0030\u004c\u005e\u004d\u004d\u0026\u004b\u0042\u0076\u006b\u006e\u0041\u0046\u0021\u0056\u0065\u0048\u007e\u003e\u003e\u006c\u0049\u0028\u0068\u0076\u0025\u005f\u004b\u0049\u0063\u006e\u003e\u0069\u0073\u006f\u0071\u002a\u0047\u005d\u0044\u004a\u0032\u0059\u0073\u006c\u0067\u0075\u0029\u0037\u0034\u002c\u005c\u0063\u0075\u0062\u006a\u003f\u0047\u0024\u004a\u0055\u0057\u0079\u0031\u0034\u0034\u006f\u0020\u0063\u0024\u0077\u0023\u002e\u0058\u0051\u0046\u0077\u0052\u0051\u006b\u0045\u0028\u0030\u0042\u0034\u005c\u0051\u0020\u003d\u005d\u003c\u0070\u002f\u0029\u007d\u0047\u003d\u007d\u005d\u0061\u0036\u0042\u003c\u0052\u0062\u003c\u0072\u0052\u002f\u0039\u0026\u0072\u007e\u002e\u0026\u0052\u0078\u0067\u0028\u0077\u0037\u0038\u0068\u0023\u0065\u0061\u0049\u0076\u0068\u0071\u0035\u0021\u0059\u0026\u0076\u0059\u007a\u004f\u0064\u0063\u0020\u007d\u002d\u0062\u004c\u0066\u006f\u0025\u007c\u0042\u0043\u0054\u0077\u0067\u003f\u0057\u0063\u007c\u0064\u0048\u0075\u0021\u003c\u0079\u003b\u0055\u002b\u0038\u003d\u0057\u006a\u0060\u007d\u0056\u002a\u0063\u004a\u003b\u0064\u0056\u0028\u0043\u0065\u0053\u003b\u003f\u0077\u0037\u0031\u005f\u0074\u0046\u004d\u003d\u0055\u0038\u0044\u0023\u0076\u0041\u0070\u0075\u0054\u007d\u0048\u0045\u0075\u0061\u0047\u007e\u007d\u0072\u0068\u0021\u0027\u0031\u0049\u0065\u004c\u002f\u0069\u0025\u007c\u007d\u007a\u002c\u002a\u0053\u0054\u0050\u0021\u002b\u002d\u006c\u0043\u002e\u007a\u0050\u003e\u007e\u005b\u0043\u0060\u004b\u0024\u0039\u007b\u0031\u0063\u002e\u004b\u0075\u002d\u0075\u0043\u0058\u005f\u0070\u003e\u007b\u004e\u006e\u0041\u0065\u0037\u005b\u0026\u0053\u002c\u004e\u0057\u005c\u0034\u004d\u0065\u007d\u007c\u0029\u0070\u0067\u0023\u0038\u0074\u0046\u005f\u0053\u0032\u0037\u0038\u0048\u0024\u0060\u002d\u004e\u0026\u0061\u002d\u003f\u003c\u0029\u0078\u0072\u005c\u0029\u0058\u003b\u0074\u003f\u0039\u0078\u0068\u0059\u0047\u005f\u0021\u0044\u0023\u005f\u005b\u0034\u0048\u005e\u007d\u0057\u0032\u0061\u0050\u006d\u0062\u005c\u0029\u0043\u006a\u005f\u005d\u002e\u0044\u0070\u003d\u003d\u0026\u0032\u007b\u0076\u006f\u0042\u0062\u0022\u0042\u0060\u0029\u0021\u007b\u0044\u0037\u002f\u005e\u007e\u0078\u0048\u0037\u0026\u0042\u004a\u0063\u0054\u0033\u002b\u005a\u0025\u0069\u005c\u0037\u0072\u002d\u0051\u004b\u0065\u002e\u0056\u0076\u0039\u0034\u0039\u004a\u005f\u0030\u007c\u0021\u0044\u0030\u003d\u0072\u006d\u005b\u003b\u006d\u002c\u0075\u0074\u005f\u0062\u0046\u004b\u0048\u004b\u004c\u004f\u003e\u0064\u0025\u0027\u0055\u0037\u004c\u0036\u002d\u006e\u0022\u0074\u005b\u007a\u0027\u0063\u0036\u006b\u003b\u003a\u0029\u002c\u0038\u0058\u0028\u0027\u004e\u006d\u0047\u0032\u002e\u0073\u0043\u0041\u0050\u0037\u002c\u004a\u0067\u0023\u0048\u0053\u0028\u003a\u002b\u006b\u0056\u004b\u0035\u004a\u0047\u0071\u0045\u0078\u0047\u0075\u0040\u0076\u0059\u0023\u007b\u003c\u0077\u0074\u003d\u004f\u0032\u0068\u005d\u007a\u004a\u0069\u005e\u0036\u0027\u0068\u0075\u005c\u0029\u0023\u0066\u0036\u0021\u002b\u003d\u0052\u0067\u004b\u0030\u0029\u006d\u005a\u0054\u0040\u0063\u0058\u0032\u003a\u0058\u003c\u003d\u0051\u0029\u004a\u0024\u0074\u0072\u007a\u005f\u0026\u0064\u0028\u0058\u0066\u0027\u0055\u006f\u0043\u0027\u003a\u0057\u0020\u0021\u0067\u004f\u0075\u0033\u007c\u0060\u0021\u006a\u0046\u0042\u0061\u007e\u006a\u006b\u0060\u0041\u005d\u0029\u0026\u0045\u0024\u0028\u0052\u0049\u002e\u0062\u002b\u003e\u0038\u0056\u0070\u0026\u0065\u0049\u0057\u006c\u0062\u0047\u0057\u0071\u0058\u004d\u006a\u005a\u0024\u0076\u004f\u0043\u0046\u0064\u005a\u003e\u0023\u004f\u005b\u0049\u0039\u006c\u0062\u0077\u0051\u006e\u0049\u0075\u003c\u0066\u0030\u0064\u0068\u0020\u0064\u0042\u006b\u0048\u0070\u002b\u0078\u0054\u0060\u0026\u0073\u0070\u003b\u0069\u0066\u002b\u0035\u0024\u002d\u0022\u0036\u0070\u006f\u0058\u0024\u003c\u0053\u002b\u0076\u005d\u0055\u0060\u0037\u0065\u0053\u004a\u006e\u0070\u003f\u0072\u0034\u0052\u0058\u0053\u004f\u0022\u003d\u007e\u007c\u0066\u005d\u0066\u0078\u007e\u0075\u002f\u0062\u0049\u0041\u006a\u0066\u0061\u0032\u0055\u0078\u0054\u0075\u0072\u0026\u007e\u003f\u0040\u006c\u007c\u003c\u0032\u0056\u007e\u0060\u0076\u0076\u0022\u0070\u007b\u0039\u005b\u0071\u0062\u0077\u007c\u0034\u0030\u0021\u005e\u004e\u0056\u002a\u0056\u0038\u0044\u0056\u005f\u0056\u0046\u0046\u004c\u0058\u0070\u0073\u0020\u005a\u006a\u0055\u0053\u003e\u005a\u006f\u006d\u0036\u0035\u0069\u0052\u0066\u003e\u0048\u007e\u0077\u0021\u0051\u005f\u0050\u0045\u002c\u0040\u003d\u004a\u0033\u0034\u0044\u0031\u0053\u0075\u0051\u0070\u006e\u007e\u002e\u002c\u0043\u002f\u007e\u0030\u005b\u004d\u0076\u0044\u0076\u0022\u0031\u005a\u0027\u005b\u0033\u0076\u002b\u0047\u004e\u0079\u004e\u0070\u003d\u005a\u002c\u0068\u006d\u006f\u004c\u0034\u003c\u003b\u0070\u007b\u002a\u0043\u002c\u005a\u0035\u0042\u003a\u0028\u003e\u002b\u0076\u0060\u002f\u005d\u003a\u005a\u0066\u0072\u004b\u0053\u0055\u0051\u006d\u0069\u007d\u0058\u0060\u007d\u007c\u0020\u0076\u0046\u0031\u002e\u002c\u007d\u007c\u0067\u0067\u0078\u0028\u0032\u0031\u0049\u005d\u0029\u0061\u0070\u0025\u0027\u0036\u0022\u002d\u0027\u004b\u0022\u004b\u0066\u003c\u0064\u0046\u0052\u005d\u0030\u003f\u0070\u0056\u005a\u0051\u005f\u0036\u004e\u0077\u0040\u0078\u005c\u0045\u0040\u0078\u007c\u006c\u0052\u003e\u0057\u0061\u0059\u003e\u0038\u004d\u005f\u004c\u0034\u006c\u005d\u0024\u0052\u004c\u0074\u0059\u002b\u0071\u003b\u003b\u003f\u0035\u007b\u0035\u006e\u002b\u002c\u0078\u0023\u0041\u0050\u0024\u0041\u0077\u005a\u0036\u0025\u002a\u0072\u0022\u0049\u0041\u0042\u0025\u007a\u0024\u007a\u0072\u0047\u0049\u0036\u003d\u006c\u005e\u004b\u0076\u0026\u0074\u006a\u004b\u003b\u0034\u0032\u0036\u0063\u006a\u0041\u0023\u0038\u002b\u0041\u0062\u0032\u0031\u0062\u0067\u007a\u004d\u0037\u004d\u0020\u0026\u0044\u0045\u0025\u0036\u0077\u003e\u0065\u0035\u0033\u005a\u0043\u0059\u0049\u0031\u0068\u0052\u0073\u002d\u003f\u0024\u0026\u005d\u0036\u0077\u0049\u006d\u007c\u003c\u0032\u0055\u005b\u007e\u0069\u0054\u0051\u005c\u0075\u0024\u0062\u0079\u006d\u006f\u0077\u0042\u004f\u007b\u0066\u005a\u0037\u0024\u0021\u0068\u0024\u0065\u004c\u007e\u003c\u0022\u0068\u0047\u0075\u0024\u0033\u0079\u007e\u0034\u004c\u0039\u003c\u0058\u0073\u006d\u0067\u0060\u0029\u007b\u0031\u0074\u006a\u0058\u0039\u007b\u005f\u0055\u0033\u0035\u003f\u0048\u007e\u0068\u0058\u002a\u0030\u007e\u0030\u0071\u0059\u004a\u0060\u0074\u0038\u004a\u0040\u0051\u0041\u0025\u0056\u0021\u0079\u007c\u006e\u0024\u0058\u0052\u0045\u004c\u006a\u0071\u0073\u0025\u007c\u005b\u004e\u0054\u002c\u0043\u0027\u0036\u0029\u006b\u006d\u0042\u0020\u006a\u003a\u0028\u0045\u004e\u0057\u003b\u003a\u0051\u0056\u0021\u0049\u0024\u0044\u0072\u0063\u007b\u0071\u0049\u0071\u003f\u004b\u0040\u0029\u005c\u0057\u0076\u0058\u006d\u006b\u0046\u0051\u006f\u0029\u0046\u005b\u0020\u0061\u0072\u004c\u0049\u0077\u0021\u0034\u0069\u0024\u004d\u0073\u0034\u0078\u002f\u006e\u0038\u0020\u005d\u0079\u0059\u002c\u002e\u004a\u0069\u0034\u0034\u0035\u0055\u005c\u0054\u002d\u0077\u006e\u004f\u003d\u0050\u007e\u006b\u0066\u0077\u0053\u0027\u0062\u0073\u007a\u0023\u0058\u005d\u007d\u0021\u004b\u0069\u0055\u0062\u0051\u0049\u002c\u005c\u002f\u0033\u006c\u002f\u0071\u0033\u006f\u0035\u0048\u005d\u004d\u004e\u0039\u0030\u0031\u0062\u0073\u0052\u0056\u007a\u0052\u0078\u0061\u0050\u006d\u0056\u003c\u003f\u0026\u0036\u0066\u0049\u0046\u007d\u0022\u003c\u0023\u0026\u004e\u007b\u0044\u007b\u0034\u005d\u0061\u0051\u0031\u003e\u0055\u005a\u0037\u0052\u0067\u0062\u0034\u0059\u0027\u0035\u0025\u0030\u004e\u0040\u003f\u0065\u0052\u004f\u0035\u0063\u005b\u0068\u003b\u0071\u0076\u0028\u002c\u0053\u0042\u0076\u002e\u003f\u002a\u006b\u0068\u0052\u0046\u0021\u0054\u0026\u0055\u0042\u003c\u0050\u004f\u0030\u002e\u0076\u0039\u005b\u005a\u007a\u0069\u007d\u002d\u0057\u0039\u003f\u003f\u0038\u007b\u0032\u0045\u0035\u003e\u0076\u006c\u0040\u004e\u0023\u0025\u0055\u005f\u0043\u006e\u0059\u003d\u0050\u0061\u003c\u006f\u0078\u005b\u0066\u0064\u007b\u0032\u0061\u0032\u006e\u004b\u006c\u0048\u006b\u0050\u0075\u002a\u0033\u0077\u0058\u0056\u002a\u004f\u0028\u006d\u0026\u002d\u0062\u0033\u0041\u0028\u0042\u0072\u0037\u003a\u006d\u002f\u0021\u0061\u0028\u0078\u0054\u0046\u0056\u004a\u0032\u0029\u007a\u002c\u004b\u0077\u0077\u0043\u0062\u004e\u0033\u007c\u0053\u0039\u002d\u0025\u0032\u0040\u0038\u005a\u0045\u002b\u007c\u002a\u0032\u0074\u0051\u004f\u006a\u002e\u0031\u0044\u0073\u005f\u0029\u007d\u0050\u0057\u0026\u006f\u0057\u0055\u0051\u0057\u0051\u003d\u006d\u004c\u006a\u0057\u0048\u005c\u006f\u0063\u002f\u002f\u0070\u0047\u0040\u006d\u0039\u0077\u0063\u007e\u0059\u0076\u005c\u0029\u0033\u0051\u0057\u0072\u0039\u0079\u0054\u0061\u005b\u003d\u0072\u0068\u003c\u005e\u005a\u005b\u0037\u005d\u006e\u0060\u0062\u0070\u003e\u0070\u0048\u007c\u0036\u0059\u0039\u0036\u0056\u0053\u0020\u005f\u0053\u0070\u0077\u0021\u006b\u005e\u0035\u0039\u0068\u0077\u002a\u0043\u0046\u0068\u004f\u0069\u0028\u0066\u002b\u0067\u0036\u0022\u0034\u007a\u0042\u0040\u005f\u007c\u0029\u0054\u0071\u007d\u0067\u005c\u002c\u002b\u0020\u0029\u0061\u0071\u0020\u005b\u003e\u006d\u0078\u002e\u0022\u0049\u006f\u002f\u0072\u006d\u0077\u0076\u002b\u0048\u0023\u0039\u0056\u0063\u0067\u007d\u002c\u005e\u0053\u005d\u006e\u0057\u0071\u0051\u0068\u0027\u0041\u0076\u007d\u0028\u0030\u0029\u0049\u006b\u007c\u0020\u0068\u0024\u0060\u0075\u0077\u0077\u0076\u0056\u0027\u0047\u0069\u006a\u0066\u0037\u0052\u0069\u004d\u0075\u0043\u0056\u005f\u0022\u0062\u0068\u0065\u0048\u0029\u0065\u007e\u0034\u0042\u0077\u0056\u0054\u0043\u0040\u0048\u0035\u0066\u0034\u002c\u006b\u003f\u002a\u0022\u0078\u002f\u0031\u0029\u0020\u0073\u0067\u0070\u0043\u0031\u0072\u0024\u0063\u0022\u0047\u0042\u0020\u0075\u006b\u0068\u0034\u0075\u0034\u0027\u003e\u006e\u0044\u002b\u0055\u0032\u004d\u0059\u0052\u005c\u0037\u006e\u0021\u0032\u0021\u002f\u006c\u0047\u0052\u0035\u0050\u0044\u0029\u0063\u005b\u0031\u002c\u002b\u0065\u0042\u0078\u005c\u0071\u0070\u0038\u007d\u0057\u0032\u0033\u0020\u0039\u003d\u005f\u0026\u0031\u0064\u003d\u002c\u0043\u0032\u002f\u0023\u0044\u003d\u0074\u0033\u005f\u006b\u0075\u0073\u0038\u006d\u007a\u007a\u0022\u0021\u0038\u0067\u003b\u0046\u006b\u0076\u0052\u0069\u006b\u005d\u0055\u0058\u0062\u0056\u006d\u003c\u0043\u005f\u0042\u006b\u0052\u0036\u006c\u0048\u0035\u0054\u005b\u0079\u0052\u006b\u0054\u0031\u004b\u004c\u0072\u0079\u007d\u003b\u002b\u0039\u004c\u0024\u0054\u0035\u0032\u0053\u0023\u0063\u0035\u0062\u0038\u0063\u0034\u0072\u004b\u0061\u003b\u007a\u0066\u0026